// about beats two they have to keep in step.
func batchSyncCmd(repoPaths []string, spec syncSpec) tea.Cmd {
	sem := make(chan struct{}, max(spec.jobs, 1))
	cmds := make([]tea.Cmd, len(repoPaths))
